Use `t.TempDir()` so tests never touch real user data. Test round-tripping, missing files, and invalid JSON:

```go
func TestSaveAndLoadBooks(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "nested", "books.json")

	want := []Book{
		{ID: 1, Title: "Dune", Author: "Frank Herbert", Status: "reading"},
		{ID: 2, Title: "The Hobbit", Author: "J.R.R. Tolkien", Status: "finished"},
	}

	if err := SaveBooks(path, want); err != nil {
		t.Fatalf("SaveBooks() error = %v", err)
	}

	got, err := LoadBooks(path)
	if err != nil {
		t.Fatalf("LoadBooks() error = %v", err)
	}

	if !reflect.DeepEqual(got, want) {
		t.Errorf("loaded books = %#v, want %#v", got, want)
	}
}

func TestLoadBooksMissingFile(t *testing.T) {
	path := filepath.Join(t.TempDir(), "books.json")

	got, err := LoadBooks(path)
	if err != nil {
		t.Fatalf("LoadBooks() error = %v", err)
	}

	if len(got) != 0 {
		t.Errorf("loaded %v books, want an empty list", len(got))
	}
}

func TestLoadBooksInvalidJSON(t *testing.T) {
	path := filepath.Join(t.TempDir(), "books.json")

	if err := os.WriteFile(path, []byte("{invalid"), 0o600); err != nil {
		t.Fatal(err)
	}

	if _, err := LoadBooks(path); err == nil {
		t.Fatal("LoadBooks() expected an error for invalid JSON")
	}
}
```

Imports:

```go
import (
	"os"
	"path/filepath"
	"reflect"
	"testing"
)
```

Run them with:

```bash
go test ./...
```
